/// The schema library's name, as its `/GLOBAL` prim declares it.
pub const LIBRARY: &str = "observatory";

/// The OpenUSD domains the library's schemas build on, which a
/// registry of them also registers ([`registry`]).
pub const DEPENDENCIES: &[::layerstack_schemas::Domain] = &[::layerstack_schemas::Domain::UsdGeom];

/// Registers the library's schemas, auto-applies and metadata
/// declarations with `builder`, interning their names in `tokens`, the
/// interner of the store whose stages use the registry. The OpenUSD
/// schemas they build on are registered separately
/// (`layerstack_schemas::register` with [`DEPENDENCIES`]).
///
/// # Errors
///
/// A metadata declaration that conflicts with one already registered.
pub fn register(
    builder: &mut ::layerstack::SchemaRegistryBuilder,
    tokens: &mut ::layerstack::TokenInterner,
) -> Result<(), ::layerstack::MetadataConflict> {
    TABLES.register(builder, tokens)
}

/// A registry of the library's schemas and of the OpenUSD schemas they
/// build on ([`DEPENDENCIES`]).
///
/// # Errors
///
/// A metadata declaration of the library that conflicts with one of
/// OpenUSD's.
pub fn registry(
    tokens: &mut ::layerstack::TokenInterner,
) -> Result<::layerstack::SchemaRegistry, ::layerstack::MetadataConflict> {
    let mut builder = ::layerstack::SchemaRegistry::builder();
    ::layerstack_schemas::register(&mut builder, DEPENDENCIES, tokens)?;
    register(&mut builder, tokens)?;
    Ok(builder.build(tokens))
}

